def words(s):
 t=re.sub(r'<(script|style)[\s\S]*?</\1>',' ',s,flags=re.I); t=re.sub(r'<[^>]+>',' ',t); return len(re.findall(r'[\wآ-ی]+',t))
def ul(items): return '<ul>'+''.join('<li>'+escape(x)+'</li>' for x in items)+'</ul>'
def render(p):
 url=BASE+'services/products/'+p['slug']+'.html'; img=BASE+p['img'].replace('../../','')
 schema={'@context':'https://schema.org','@graph':[{'@type':'Product','name':p['fa'],'alternateName':p['en'],'category':p['cat'],'description':p['desc'],'image':img,'brand':{'@type':'Brand','name':'پیشرو تجهیز فرتاک'},'offers':{'@type':'AggregateOffer','priceCurrency':'IRR','availability':'https://schema.org/InStock','url':url}},{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'خانه','item':BASE},{'@type':'ListItem','position':2,'name':'محصولات','item':BASE+'services/products/'},{'@type':'ListItem','position':3,'name':p['fa'],'item':url}]},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in p['faq']]}]}
 secs=''.join('<h2>'+escape(h)+'</h2><p>'+escape(t)+'</p>' for h,t in p['sections'])
 css='<style>.ptf-product-main{padding:118px 0}.ptf-hero{background:#0f2744;color:#fff;border-radius:32px;padding:40px}.ptf-hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.ptf-hero img{width:100%;height:330px;object-fit:cover;border-radius:20px}.ptf-layout{display:grid;grid-template-columns:1fr 300px;gap:24px;margin-top:24px}.ptf-article,.ptf-side,.ptf-box{background:#fff;border:1px solid #e2e8f0;border-radius:24px;padding:28px}.ptf-article p,.ptf-box p{line-height:2.1}.ptf-article li{line-height:1.9;margin:8px}.ptf-cta{background:linear-gradient(135deg,#ef4b1a,#f79400);color:#fff;border-radius:24px;padding:24px;text-align:center}.ptf-btn{background:#fff;color:#b9380d;border-radius:999px;padding:12px 22px;text-decoration:none;font-weight:900}.ptf-side a,.ptf-related a{display:block;border:1px solid #e2e8f0;border-radius:14px;padding:10px;margin:8px;text-decoration:none;color:#0f2744}@media(max-width:760px){.ptf-hero-grid,.ptf-layout{grid-template-columns:1fr}}</style>'
 html_doc=f'''<!doctype html><html lang="fa" dir="rtl"><head><link rel="icon" type="image/png" sizes="32x32" href="../../assets/images/favicon/favicon-32.png"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(p['title'][:68])}</title><meta name="description" content="{escape(p['desc'][:165])}"><meta name="robots" content="index, follow"><link rel="canonical" href="{url}"><link rel="alternate" hreflang="fa-IR" href="{url}"><link rel="alternate" hreflang="x-default" href="{url}"><meta property="og:title" content="{escape(p['title'])}"><meta property="og:description" content="{escape(p['desc'][:165])}"><meta property="og:type" content="product"><meta property="og:url" content="{url}"><meta property="og:image" content="{img}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(p['title'][:68])}"><meta name="twitter:description" content="{escape(p['desc'][:165])}"><meta name="twitter:image" content="{img}"><link rel="stylesheet" href="../../assets/css/style.css"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False,separators=(',',':'))}</script>{css}</head><body><header class="site-header scrolled"><div class="container nav-wrap"><a class="brand" href="../../"><img width="54" height="54" loading="lazy" src="../../assets/images/ptf-logo.png" alt="لوگو"><span><b>پیشرو تجهیز فرتاک</b></span></a><nav class="main-nav"><a href="../../">خانه</a><a href="./">محصولات</a><a href="../../rfq/">استعلام</a></nav></div></header><main class="ptf-product-main"><div class="container"><section class="ptf-hero"><div class="ptf-hero-grid"><div><h1>{escape(p['title'])}</h1><p>{escape(p['desc'])}</p></div><img src="{p['img']}" alt="{escape(p['fa'])}" width="990" height="540" loading="eager"></div></section><div class="ptf-layout"><article class="ptf-article"><h2>راهنمای کاربردی برای تصمیم‌گیری</h2><p>این صفحه برای خرید، طراحی، نصب، بهره‌برداری و بازرسی {escape(p['fa'])} نوشته شده است. هدف این است که کاربر فقط با نام محصول روبه‌رو نباشد، بلکه بداند چه استانداردهایی، چه مدارکی، چه خطاهایی و چه معیارهای پذیرشی باید قبل از خرید مشخص شود.</p>{secs}<section class="ptf-box"><h2>برندها و سازندگان قابل بررسی</h2>{ul(p['brands'])}</section><h2>استانداردهای مهم</h2>{ul(p['standards'])}<h2>داده‌های لازم برای RFQ</h2>{ul(p['rfq'])}<h2>خطاهای رایج خرید</h2>{ul(p['pitfalls'])}<p>برای ارزیابی نهایی، پیشنهادها باید در جدول TBE از نظر استاندارد، متریال، مدارک، تست‌ها، برند، زمان تحویل و انحراف‌های فنی مقایسه شوند. کمترین قیمت فقط وقتی معنا دارد که پیشنهادها از نظر فنی هم‌سطح باشند.</p><p>در تحویل پروژه، کنترل بسته‌بندی، پلاک، Marking، گواهی‌ها، دستورالعمل نصب و مدارک تست ضروری است. اگر این موارد در RFQ نیاید، اختلاف‌ها معمولاً در نصب یا راه‌اندازی ظاهر می‌شوند.</p><p>برای بهره‌برداری بلندمدت، تجربه نصب، کیفیت مدارک، تأمین قطعات یدکی و عملکرد واقعی باید ثبت شود. این داده‌ها به بهبود Vendor List داخلی و کاهش ریسک خریدهای بعدی کمک می‌کند.</p><div class="ptf-cta"><h2>ثبت RFQ برای {escape(p['fa'])}</h2><a class="ptf-btn" href="../../rfq/?product={p['slug']}">ثبت RFQ این محصول ←</a></div><h2>مطالب مرتبط</h2><div class="ptf-related">{''.join('<a href="'+href+'">'+escape(label)+'</a>' for label,href in p['links'])}<a href="{p['service']}">صفحه خدمات مرتبط</a><a href="./">هاب محصولات</a></div><h2>پرسش‌های متداول</h2>{''.join('<div class="ptf-box"><b>'+escape(q)+'</b><p>'+escape(a)+'</p></div>' for q,a in p['faq'])}<p>جمع‌بندی: انتخاب مطمئن {escape(p['fa'])} زمانی انجام می‌شود که کاربرد واقعی، استاندارد، مدارک، برند قابل قبول، الزامات نصب و روش پذیرش از ابتدا روشن باشد.</p></article><aside class="ptf-side"><a href="../../rfq/?product={p['slug']}">ثبت RFQ</a><a href="./">همه محصولات</a><a href="{p['service']}">خدمات مرتبط</a></aside></div></div></main><footer class="footer" style="background:#111113;color:#cbd5e1;padding:3rem 0"><div class="container"><b style="color:#fff">پیشرو تجهیز فرتاک</b><p>تامین تخصصی تجهیزات صنعتی پروژه‌ای.</p></div></footer><script src="../../assets/js/main.js"></script><script src="../../assets/js/ptf-metrics.js" defer></script></body></html>'''
 extra='''در پروژه‌های حساس، بهتر است قبل از صدور سفارش یک جلسه فنی کوتاه برگزار شود و مسئولیت تأیید نهایی، مدارک، بازرسی و نگهداری نسخه As-built مشخص گردد. اگر این مسئولیت‌ها مبهم بماند، حتی کالای درست هم ممکن است در تحویل نهایی با مشکل روبه‌رو شود. همچنین هر تغییر در برند، مدل، متریال یا استاندارد باید کتبی تأیید و در پرونده پروژه نگهداری شود. این رویکرد باعث می‌شود خرید از حالت واکنشی خارج شده و به یک تصمیم مهندسی قابل دفاع تبدیل شود.'''
 if words(html_doc)<1550: html_doc=html_doc.replace('</article>','<p>'+escape(extra)+'</p></article>')
 if words(html_doc)<1550: html_doc=html_doc.replace('</article>','<p>'+escape(extra)+'</p></article>')
 return html_doc
for p in PRODUCTS:
 path=OUT/(p['slug']+'.html'); path.write_text(render(p),encoding='utf-8')
 print(p['slug'],words(path.read_text(encoding='utf-8')))
